// Aggregate Jobs v8 — tier-aware ordering
// Changes vs v7:
//   - Sort key is (source_tier ASC, updated_at DESC) instead of pure recency
//   - Tier 4 entries (clearly not real job pages) are dropped
//   - Result count in `tier_counts` for downstream display

const allJobs = [];
const seen = new Set();
const sourceCounts = {};

for (const item of $input.all()) {
  const jobs = item.json.jobs || [];
  const source = item.json.source || 'unknown';
  sourceCounts[source] = (sourceCounts[source] || 0) + jobs.length;
  for (const job of jobs) {
    if (!job || !job.url) continue;
    const dedupKey = job.url.replace(/[?#].*$/, '').replace(/\/+$/, '').toLowerCase();
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    allJobs.push(job);
  }
}

const expandCtx = $('Parse Expand Query').first().json;
const roleFamilies    = expandCtx.role_families    || [];
const excludedRoles   = expandCtx.excluded_roles   || [];
const locationCanon   = (expandCtx.location_canonical || '').trim().toLowerCase();
const remotePref      = expandCtx.remote_preference  || 'open';
const freshness       = expandCtx.freshness          || 'qdr:w';

const freshnessMs = { 'qdr:h': 3600000, 'qdr:d': 86400000, 'qdr:w': 604800000, 'qdr:m': 2592000000, 'qdr:y': 31536000000 }[freshness] || 604800000;
const cutoff = Date.now() - freshnessMs;

let filtered = allJobs;

// Drop Tier 3 aggregators and Tier 4 unknown pages from the main ranked results.
// Aggregators are usually listing pages and often score falsely high without a full JD.
filtered = filtered.filter(j => (j.source_tier || 4) < 3);

// Role family filter
if (roleFamilies.length > 0) {
  filtered = filtered.filter(j => {
    const haystack = (j.title + ' ' + (j.department || '')).toLowerCase();
    if (excludedRoles.some(excl => {
      const terms = excl.toLowerCase().split(/\s+/);
      return terms.every(t => new RegExp('\\b' + t + '\\b').test(haystack));
    })) return false;
    return roleFamilies.some(variant => {
      const terms = variant.toLowerCase().split(/\s+/).filter(t => t.length > 1);
      return terms.every(term => term.length <= 3
        ? new RegExp('\\b' + term + '\\b').test(haystack)
        : haystack.includes(term));
    });
  });
}

// Location filter (hard, only when set and not remote_only)
if (remotePref !== 'remote_only' && locationCanon && !['any','anywhere','worldwide'].includes(locationCanon)) {
  const locTerms = locationCanon.split(/[\s,]+/).filter(t => t.length > 1);
  filtered = filtered.filter(j => {
    const src = (j.source || '').toLowerCase();
    if (src.includes('firecrawl') || src.includes('serper') || src.includes('youcom')) return true;
    const hay = (j.location || '').toLowerCase();
    if (!hay || hay === 'unknown') return true;
    return locTerms.some(t => hay.includes(t));
  });
}

// Recency filter (soft)
filtered = filtered.filter(j => {
  if (!j.updated_at) return true;
  const t = new Date(j.updated_at).getTime();
  return isNaN(t) || t >= cutoff;
});

// Sort: tier first (Tier 1 ATS at top), then recency within tier
filtered.sort((a, b) => {
  const tierDiff = (a.source_tier || 99) - (b.source_tier || 99);
  if (tierDiff !== 0) return tierDiff;
  const ad = new Date(a.updated_at || 0).getTime() || 0;
  const bd = new Date(b.updated_at || 0).getTime() || 0;
  return bd - ad;
});

// Tier composition for downstream display
const tierCounts = { 1: 0, 2: 0, '2.5': 0, 3: 0 };
for (const j of filtered) {
  const t = j.source_tier;
  if (t === 1) tierCounts[1]++;
  else if (t === 2) tierCounts[2]++;
  else if (t === 2.5) tierCounts['2.5']++;
  else if (t === 3) tierCounts[3]++;
}

const top = filtered.slice(0, 50);
return [{ json: {
  jobs: top, count: top.length, total_raw: allJobs.length,
  sources: sourceCounts, tier_counts: tierCounts,
  filter_applied: { role_families: roleFamilies, location: locationCanon || null, remote_preference: remotePref }
} }];

// Build Scorer Input v5 — resume_bubbles aware, compact by default.
const jobs = $('Experience Filter').first().json.jobs || [];
const sd = $getWorkflowStaticData('global');

function parseMaybe(v) {
  if (!v) return null;
  if (typeof v === 'string') { try { return JSON.parse(v); } catch(e) { return v; } }
  return v;
}
function firstPrimary(arr) {
  return Array.isArray(arr) ? (arr.find(x => x && x.primary) || arr[0] || {}) : {};
}
function clean(v) {
  const s = (v === null || v === undefined) ? '' : String(v).trim();
  if (!s || s.toLowerCase() === 'undefined' || s.toLowerCase() === 'null') return '';
  return s;
}
function locToString(loc) {
  if (!loc) return '';
  if (typeof loc === 'string') return clean(loc);
  return [loc.city, loc.region, loc.country].map(clean).filter(Boolean).join(', ');
}
function flatSkills(skills) {
  const out = [];
  if (skills && typeof skills === 'object') {
    for (const vals of Object.values(skills)) if (Array.isArray(vals)) out.push(...vals);
  }
  return [...new Set(out.map(s => String(s).trim()).filter(Boolean))];
}
function summarizeBubbles(r) {
  const parts = [];
  const p = r.personal || r.profile || {};
  const email = firstPrimary(p.emails).address || p.email || '';
  const loc = locToString(firstPrimary(p.locations)) || p.location || '';
  if (p.name) parts.push('CANDIDATE: ' + p.name);
  if (p.headline) parts.push('HEADLINE: ' + p.headline);
  if (email || loc) parts.push('CONTACT CONTEXT: ' + [email, loc].filter(Boolean).join(' | '));
  const wa = p.work_authorization;
  if (wa) parts.push('WORK AUTHORIZATION: ' + (typeof wa === 'object' ? Object.entries(wa).map(([k, v]) => k + ': ' + v).join(' | ') : String(wa)));
  const skillsList = flatSkills(r.skills);
  if (skillsList.length) parts.push('SKILLS: ' + skillsList.slice(0, 55).join(', '));
  const exp = Array.isArray(r.experience) ? r.experience : [];
  if (exp.length) {
    parts.push('EXPERIENCE EVIDENCE:\n' + exp.slice(0, 5).map(e => {
      const title = [e.title, e.company || e.organization].filter(Boolean).join(' @ ');
      const bullets = (e.bullets || []).slice(0, 4).map(b => '- ' + b).join('\n');
      return title + (bullets ? '\n' + bullets : '');
    }).join('\n\n'));
  }
  const projects = Array.isArray(r.projects) ? r.projects : [];
  if (projects.length) {
    parts.push('PROJECT EVIDENCE:\n' + projects.slice(0, 4).map(pj => {
      const title = pj.name || pj.title || 'Project';
      const bullets = (pj.bullets || []).slice(0, 3).map(b => '- ' + b).join('\n');
      return title + (bullets ? '\n' + bullets : '');
    }).join('\n\n'));
  }
  const edu = Array.isArray(r.education) ? r.education : [];
  if (edu.length) parts.push('EDUCATION: ' + edu.map(e => [e.degree, e.field, e.institution].filter(Boolean).join(' ')).join(' | '));
  return parts.join('\n\n').substring(0, 3500);
}
function summarizeStructured(r) {
  if (!r || typeof r !== 'object') return '';
  if (r.kind === 'resume_bubbles') {
    const compact = r.compact_views?.scoring_profile || r.compact_views?.search_profile || '';
    return (compact || summarizeBubbles(r)).substring(0, 3500);
  }
  const parts = [];
  const p = r.personal || {};
  const email = firstPrimary(p.emails).address || p.email || '';
  const loc = locToString(firstPrimary(p.locations)) || p.location || '';
  if (p.name) parts.push('CANDIDATE: ' + p.name);
  if (p.headline) parts.push('HEADLINE: ' + p.headline);
  if (email || loc) parts.push('CONTACT CONTEXT: ' + [email, loc].filter(Boolean).join(' | '));
  if (Array.isArray(r.summary_bullets) && r.summary_bullets.length) {
    parts.push('SUMMARY:\n' + r.summary_bullets.slice(0, 6).map(b => '- ' + b).join('\n'));
  }
  if (Array.isArray(r.experience) && r.experience.length) {
    const expBlocks = r.experience.slice(0, 5).map(e => {
      const dates = (e.start_date || '?') + ' to ' + (e.is_current ? 'current' : (e.end_date || '?'));
      const bullets = [];
      (e.projects || []).slice(0, 3).forEach(pr => {
        if (pr.name) bullets.push('Project: ' + pr.name + (Array.isArray(pr.tech) && pr.tech.length ? ' [' + pr.tech.slice(0, 8).join(', ') + ']' : ''));
        (pr.bullets || []).slice(0, 4).forEach(b => bullets.push(b));
      });
      (e.bullets || []).slice(0, 4).forEach(b => bullets.push(b));
      return (e.title || 'Role') + ' @ ' + (e.company || e.organization || 'Company') + ' (' + dates + ')' + (bullets.length ? '\n  ' + bullets.slice(0, 8).map(b => '- ' + b).join('\n  ') : '');
    });
    parts.push('EXPERIENCE:\n' + expBlocks.join('\n\n'));
  }
  if (Array.isArray(r.projects) && r.projects.length) {
    const projBlocks = r.projects.slice(0, 6).map(pj => {
      const tech = Array.isArray(pj.tech) && pj.tech.length ? ' [' + pj.tech.slice(0, 8).join(', ') + ']' : '';
      const bullets = (pj.bullets || []).slice(0, 3).map(b => '- ' + b).join('\n  ');
      return (pj.name || pj.title || 'Project') + tech + (bullets ? '\n  ' + bullets : '');
    });
    parts.push('PROJECTS:\n' + projBlocks.join('\n'));
  }
  const skillsList = flatSkills(r.skills);
  if (skillsList.length) parts.push('SKILLS: ' + skillsList.slice(0, 60).join(', '));
  if (Array.isArray(r.education) && r.education.length) {
    parts.push('EDUCATION: ' + r.education.map(e => [e.degree, e.field, e.institution].filter(Boolean).join(' ') + (e.gpa ? ' GPA ' + e.gpa : '')).join(' | '));
  }
  return parts.join('\n\n').substring(0, 6000);
}

const rows = $input.all().map(i => i.json || {});
let row = rows.find(r => r && (r.id === 'global:resume_structured' || r.value)) || rows[0] || {};
let resume = parseMaybe(row.value || null);
if (resume && resume.resume_doc) resume = resume.resume_doc;
if ((!resume || typeof resume !== 'object' || !resume.personal) && sd.last_resume_structured) resume = sd.last_resume_structured;
if ((!resume || typeof resume !== 'object') && sd.last_resume_json) resume = sd.last_resume_json;

let resumeSummary = summarizeStructured(resume);
let resumeMissing = !resumeSummary;
if (resumeMissing) resumeSummary = 'No resume found - please run resume setup first';

const jobBatch = jobs.map(j => ({
  job_id: j.job_id, title: j.title, company: j.company, location: j.location,
  department: j.department, url: j.url, description_snippet: j.description_snippet,
  source: j.source, source_tier: j.source_tier, source_tier_label: j.source_tier_label || j.tier_label,
  required_yoe_min: j.required_yoe_min ?? null, required_yoe_max: j.required_yoe_max ?? null,
  yoe_compat_score: j.yoe_compat_score ?? null
}));

return [{ json: {
  master_resume_summary: resumeSummary,
  resume_missing: resumeMissing,
  resume_kind: resume && typeof resume === 'object' ? (resume.kind || 'structured') : 'none',
  resume_source: resumeMissing ? 'none' : (row.id ? 'supabase' : 'staticData'),
  jobs: jobBatch
} }];

const staticData = $getWorkflowStaticData('global');
const chatId = $('Extract Input').first().json.chat_id;
const rawMessage = $('Telegram Trigger').first().json.message?.text || '';
const entities = $('Route Intent').first().json.output?.entities || {};
const jobNumber = entities.job_number;
const urlMatch = rawMessage.match(/https?:\/\/[^\s]+/);
if (urlMatch) {
  const jobUrl = decodeURIComponent(urlMatch[0]);
  let company = 'unknown'; let source = 'web';
  const m = { ashby: jobUrl.match(/jobs\.ashbyhq\.com\/([^\/]+)\//), lever: jobUrl.match(/jobs\.lever\.co\/([^\/]+)\//), greenhouse: jobUrl.match(/(?:boards|job-boards)\.greenhouse\.io\/([^\/]+)\//), workday: jobUrl.match(/([^.]+)\.wd\d+\.myworkdayjobs\.com\//), workable: jobUrl.match(/apply\.workable\.com\/([^\/]+)\//) };
  for (const [src, match] of Object.entries(m)) { if (match) { company = match[1]; source = src; break; } }
  return [{ json: { chat_id: chatId, job_number: 0, direct_url: jobUrl, source, company_slug: company, greenhouse_id: null, job: { job_id: `direct-${company}-0`, title: '', company, location: '', url: jobUrl, description_snippet: '' } } }];
}
if (!jobNumber) return [{ json: { chat_id: chatId, error: 'No job number provided. Reply with a number (1-5) after a job search, or paste a job URL directly.' } }];
const lastJobs = staticData.last_jobs || {};
const job = lastJobs[jobNumber];
if (!job) return [{ json: { chat_id: chatId, error: `Job #${jobNumber} not found. Run a job search first, or paste a job URL directly.` } }];
const parts = job.job_id.split('-');
const greenhouseId = parts.pop();
const companySlug = parts.join('-');
return [{ json: { chat_id: chatId, job_number: jobNumber, company_slug: companySlug, greenhouse_id: greenhouseId, source: job.source || 'greenhouse', job } }];

const retrieveData = $('Retrieve Job').first().json;
const scrapeResult = $input.first().json;
let jobDescription = retrieveData.job?.description_snippet || '';
if (scrapeResult) {
  const md = scrapeResult.markdown || (scrapeResult.data && scrapeResult.data.markdown) || '';
  if (md && md.length > 100) jobDescription = md.substring(0, 8000);
}
const metadata = scrapeResult?.metadata || scrapeResult?.data?.metadata || {};
const job = retrieveData.job || {};
const jobTitle = job.title || metadata.title?.replace(/ \| .*$/, '').trim() || 'Unknown Role';
const company = job.company || retrieveData.company_slug || metadata.ogSiteName || 'unknown';
return [{ json: { chat_id: retrieveData.chat_id, job_number: retrieveData.job_number, job_title: jobTitle, company, company_slug: retrieveData.company_slug, location: job.location || metadata.geo_region || 'Unknown', job_url: retrieveData.direct_url || job.url || '', job_description: jobDescription, fit_score_from_digest: job.fit_score || null } }];

// Parse Personal Info v5 — Supabase resume_bubbles/structured resume first, legacy file fallback second.
const jobCtx = $('Prepare Job Context').first().json;

function parseMaybe(v) {
  if (!v) return null;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch(e) { return v; }
  }
  return v;
}
function firstPrimary(arr) {
  return Array.isArray(arr) ? (arr.find(x => x && x.primary) || arr[0] || {}) : {};
}
function clean(v) {
  const s = (v === null || v === undefined) ? '' : String(v).trim();
  if (!s || s.toLowerCase() === 'undefined' || s.toLowerCase() === 'null') return '';
  return s;
}
function locToString(loc) {
  if (!loc) return '';
  if (typeof loc === 'string') return clean(loc);
  return [loc.city, loc.region, loc.country].map(clean).filter(Boolean).join(', ');
}
function flatSkills(skills) {
  const out = [];
  if (skills && typeof skills === 'object') {
    for (const vals of Object.values(skills)) if (Array.isArray(vals)) out.push(...vals);
  }
  return [...new Set(out.map(s => String(s).trim()).filter(Boolean))];
}
function linesFromBubbles(r) {
  const out = [];
  const p = r.personal || r.profile || {};
  const email = firstPrimary(p.emails).address || p.email || '';
  const phone = firstPrimary(p.phones).number || p.phone_primary || p.phone || '';
  const loc = locToString(firstPrimary(p.locations)) || p.location || '';
  const links = p.links || {};
  out.push('## PERSONAL');
  out.push('name: ' + (p.name || ''));
  out.push('headline: ' + (p.headline || ''));
  out.push('email: ' + email);
  out.push('phone_primary: ' + phone);
  out.push('linkedin: ' + (links.linkedin || p.linkedin || ''));
  out.push('github: ' + (links.github || p.github || ''));
  out.push('portfolio: ' + (links.portfolio || p.portfolio || ''));
  out.push('location: ' + loc);
  out.push('');
  const compact = r.compact_views?.generation_base || r.compact_views?.scoring_profile || '';
  if (compact) {
    out.push('## COMPACT RESUME CONTEXT');
    out.push(compact);
    out.push('');
  }
  out.push('## SKILLS');
  const skillList = flatSkills(r.skills);
  if (skillList.length) out.push(skillList.join(', '));
  out.push('');
  out.push('## EXPERIENCE BUBBLES');
  (r.experience || []).slice(0, 8).forEach(e => {
    out.push([e.title, e.company || e.organization, e.start_date, e.is_current ? 'Present' : e.end_date].filter(Boolean).join(' | '));
    (e.bullets || []).slice(0, 6).forEach(b => out.push('- ' + b));
    out.push('');
  });
  out.push('## PROJECT BUBBLES');
  (r.projects || []).slice(0, 8).forEach(pj => {
    out.push((pj.name || pj.title || 'Project') + (Array.isArray(pj.tech) && pj.tech.length ? ' [' + pj.tech.slice(0, 12).join(', ') + ']' : ''));
    (pj.bullets || []).slice(0, 5).forEach(b => out.push('- ' + b));
    out.push('');
  });
  out.push('## EDUCATION');
  (r.education || []).forEach(ed => {
    out.push([ed.institution, ed.degree, ed.field, ed.location, ed.gpa ? 'GPA ' + ed.gpa : ''].filter(Boolean).join(' | '));
  });
  return out.join('\n').trim().slice(0, 7000);
}
function linesFromStructured(r) {
  if (r.kind === 'resume_bubbles') return linesFromBubbles(r);
  const out = [];
  const p = r.personal || {};
  const email = firstPrimary(p.emails).address || p.email || '';
  const phone = firstPrimary(p.phones).number || p.phone_primary || p.phone || '';
  const loc = locToString(firstPrimary(p.locations)) || p.location || '';
  const links = p.links || {};
  out.push('## PERSONAL');
  out.push('name: ' + (p.name || ''));
  out.push('headline: ' + (p.headline || ''));
  out.push('email: ' + email);
  out.push('phone_primary: ' + phone);
  out.push('linkedin: ' + (links.linkedin || p.linkedin || ''));
  out.push('github: ' + (links.github || p.github || ''));
  out.push('portfolio: ' + (links.portfolio || p.portfolio || ''));
  out.push('location: ' + loc);
  out.push('work_authorization: ' + (typeof p.work_authorization === 'string' ? p.work_authorization : JSON.stringify(p.work_authorization || {})));
  out.push('');
  if (Array.isArray(r.summary_bullets) && r.summary_bullets.length) {
    out.push('## SUMMARY');
    r.summary_bullets.forEach(b => out.push('- ' + b));
    out.push('');
  }
  out.push('## EXPERIENCES');
  (r.experience || []).forEach(e => {
    out.push([e.title, e.company || e.organization, e.location].filter(Boolean).join(' | ') + ' | ' + (e.start_date || '') + ' - ' + (e.is_current ? 'Present' : (e.end_date || '')));
    (e.projects || []).forEach(pr => {
      if (pr.name) out.push('Project: ' + pr.name + (Array.isArray(pr.tech) && pr.tech.length ? ' [' + pr.tech.join(', ') + ']' : ''));
      (pr.bullets || []).forEach(b => out.push('- ' + b));
    });
    (e.bullets || []).forEach(b => out.push('- ' + b));
    out.push('');
  });
  out.push('## PROJECTS');
  (r.projects || []).forEach(pj => {
    out.push((pj.name || pj.title || 'Project') + (Array.isArray(pj.tech) && pj.tech.length ? ' [' + pj.tech.join(', ') + ']' : ''));
    (pj.bullets || []).forEach(b => out.push('- ' + b));
    out.push('');
  });
  out.push('## EDUCATION');
  (r.education || []).forEach(ed => {
    out.push([ed.institution, ed.degree, ed.field, ed.location, ed.gpa ? 'GPA ' + ed.gpa : ''].filter(Boolean).join(' | '));
  });
  out.push('');
  out.push('## SKILLS');
  if (r.skills && typeof r.skills === 'object') {
    Object.entries(r.skills).forEach(([cat, vals]) => {
      if (Array.isArray(vals) && vals.length) out.push(cat + ': ' + vals.join(', '));
    });
  }
  return out.join('\n').trim();
}
function personalFromStructured(r) {
  const p = r.personal || r.profile || {};
  const email = firstPrimary(p.emails).address || p.email || '';
  const primaryPhone = firstPrimary(p.phones).number || p.phone_primary || p.phone || '';
  const secondaryPhone = Array.isArray(p.phones) ? ((p.phones.find(ph => !ph.primary) || {}).number || '') : (p.phone_secondary || '');
  const loc = locToString(firstPrimary(p.locations)) || p.location || '';
  const links = p.links || {};
  return {
    name: p.name || '',
    email,
    phone_primary: primaryPhone,
    phone_secondary: secondaryPhone,
    phone: primaryPhone,
    linkedin: links.linkedin || p.linkedin || '',
    github: links.github || p.github || '',
    portfolio: links.portfolio || p.portfolio || '',
    location: loc,
    show_location: false,
    work_authorization: typeof p.work_authorization === 'string' ? p.work_authorization : JSON.stringify(p.work_authorization || {})
  };
}
function parsePersonalFromText(resumeText) {
  const personal = {};
  const fieldPattern = /^(name|email|phone_primary|phone_secondary|phone|linkedin|github|portfolio|location|show_location|work_authorization):\s*(.+)/gim;
  let match;
  while ((match = fieldPattern.exec(resumeText)) !== null) {
    const key = match[1].toLowerCase();
    const val = match[2].trim();
    if (val.startsWith('[') && val.endsWith(']')) continue;
    if (val.startsWith('#')) continue;
    personal[key] = val;
  }
  if (!personal.email) {
    const em = resumeText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    if (em) personal.email = em[0];
  }
  if (!personal.phone_primary) {
    const ph = (resumeText.match(/(?:\+?\d[\d\s().-]{7,}\d)/g) || []).find(p => p.replace(/\D/g, '').length >= 10);
    if (ph) personal.phone_primary = ph.trim();
  }
  if (personal.phone && !personal.phone_primary) personal.phone_primary = personal.phone;
  return personal;
}
function applyPhoneDisplay(personal) {
  const jobLocation = (jobCtx.location || jobCtx.job_title || '').toLowerCase();
  const indiaKeywords = ['india','hyderabad','bengaluru','bangalore','mumbai','pune','delhi','chennai','kolkata','indian subcontinent'];
  const targetIsIndia = indiaKeywords.some(kw => jobLocation.includes(kw));
  personal.phone_display = targetIsIndia && personal.phone_secondary ? personal.phone_secondary : (personal.phone_primary || personal.phone_secondary || '');
  personal.show_location = String(personal.show_location || 'false').toLowerCase() === 'true';
  return personal;
}

const rows = $input.all().map(i => i.json || {});
let row = rows.find(r => r && (r.id === 'global:resume_structured' || r.value)) || rows[0] || {};
let structured = parseMaybe(row.value || null);
if (structured && structured.resume_doc) structured = structured.resume_doc;

let resumeText = '';
let personal = {};
let resumeSource = 'none';

if (structured && typeof structured === 'object' && (structured.personal || structured.profile)) {
  resumeText = linesFromStructured(structured);
  personal = personalFromStructured(structured);
  resumeSource = structured.kind === 'resume_bubbles' ? 'supabase_resume_bubbles' : 'supabase_structured';
