const hasOldContext = !!(lastApply && (lastApply.resume_json || lastApply.cover_json));
if (!hasNewContext && !hasOldContext) return [{ json: { chat_id: chatId, error: 'Nothing to revise. Apply to a job first.' } }];
return [{ json: { chat_id: chatId, change_request: $('Extract Input').first().json.message_text || '', last_apply: lastApply || {}, instruction: intentOutput.instruction || $('Extract Input').first().json.message_text || '', revise_section: intentOutput.revise_section || null, revise_tone: intentOutput.revise_tone || null, error: '' } }];

const instruction = $json.instruction || '';
const reviseSection = $json.revise_section || null;
const reviseTone = $json.revise_tone || null;
const sd = $getWorkflowStaticData('global');

const lastResumeJson = sd.last_resume_json || {};
const lastJd = sd.last_jd || '';
const lastFitStrategy = sd.last_fit_strategy || 'perfect_fit';
const lastKeywordGaps = sd.last_keyword_gaps || [];

let sectionContext = '';

if (reviseSection === 'summary') {
  sectionContext = `Rewrite ONLY the summary or objective section of this resume. Keep every other section exactly as provided in the resume JSON. Apply this instruction: ${instruction}`;
} else if (reviseSection === 'experience') {
  sectionContext = `Rewrite ONLY the experience bullet points. Do not change job titles, company names, dates, or any other sections. Apply this instruction to each bullet: ${instruction}`;
} else if (reviseSection === 'skills') {
  sectionContext = `Rewrite ONLY the skills section. Keep all other sections exactly unchanged. Apply this instruction: ${instruction}`;
} else if (reviseSection === 'keywords') {
  const gaps = lastKeywordGaps.length > 0 ? lastKeywordGaps.join(', ') : 'no specific gaps recorded';
  sectionContext = `Inject the following missing keywords naturally into the resume: ${gaps}. Add to the skills section and weave into 1-2 experience bullets where genuinely applicable. NEVER fabricate skills the candidate does not have. Additional instruction: ${instruction || 'inject all missing keywords naturally'}`;
} else {
  sectionContext = `Revise the entire resume based on this instruction: ${instruction}`;
}

if (reviseTone === 'senior') {
  sectionContext += `\n\nTone adjustment: Make the language and framing more senior. Emphasize leadership, team scope, business impact, strategic decisions, and organizational influence. Reduce emphasis on individual technical implementation tasks.`;
} else if (reviseTone === 'junior') {
  sectionContext += `\n\nTone adjustment: Make the language and framing more IC-focused. Reduce management and leadership emphasis. Increase technical depth and implementation detail. Frame as a strong individual contributor with deep execution skills.`;
} else if (reviseTone === 'neutral') {
  sectionContext += `\n\nTone adjustment: Balance IC work and leadership equally. Neither overly senior nor overly junior in framing.`;
}

return [{ json: {
  resume_json: lastResumeJson,
  jd: lastJd,
  fit_strategy: lastFitStrategy,
  keyword_gaps: lastKeywordGaps,
  section_instruction: sectionContext,
  revise_section: reviseSection,
  revise_tone: reviseTone,
} }];

function escapeLatexText(input) {
  if (typeof input !== 'string') return '';
  return input.replace(/\\/g, '\\textbackslash{}').replace(/&/g, '\\&').replace(/%/g, '\\%').replace(/\$/g, '\\$').replace(/#/g, '\\#').replace(/_/g, '\\_').replace(/\{/g, '\\{').replace(/\}/g, '\\}').replace(/\^/g, '\\textasciicircum{}').replace(/~/g, '\\textasciitilde{}');
}
function cleanText(str) {
  if (!str) return '';
  return str.replace(/\\[a-zA-Z]+\{([^}]*)\}/g, '$1').replace(/\\[a-zA-Z]+/g, '').replace(/\$[^$]*\$/g, '').trim();
}
function wrapResumeWithSkeleton(params) {
  const { skeleton, headerLatex, contentLatex } = params;
  if (!skeleton) return '\\documentclass[letterpaper,11pt]{article}\n\\begin{document}\n' + headerLatex + '\n\n' + contentLatex + '\n\\end{document}\n';
  const lines = skeleton.replace(/\r\n/g, '\n').split('\n');
  const hs = lines.findIndex(l => l.trim() === '%%% HEADER_START');
  const he = lines.findIndex((l, i) => i > hs && l.trim() === '%%% HEADER_END');
  if (hs !== -1 && he !== -1) lines.splice(hs + 1, he - hs - 1, headerLatex.trim());
  const cs = lines.findIndex(l => l.trim() === '%%% CONTENT_START');
  const ce = lines.findIndex((l, i) => i > cs && l.trim() === '%%% CONTENT_END');
  if (cs !== -1 && ce !== -1) { lines.splice(cs + 1, ce - cs - 1, contentLatex.trim()); return lines.join('\n'); }
  const endDocIdx = lines.findIndex(l => l.includes('\\end{document}'));
  if (endDocIdx !== -1) lines.splice(endDocIdx, 0, contentLatex.trim());
  else lines.push(contentLatex.trim());
  return lines.join('\n');
}
function normalizeLatexForPdflatex(input) {
  if (!input) return input;
  let s = input.replace(/\r\n/g, '\n');
  s = s.replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'").replace(/\u2026/g, '...').replace(/[\u2013\u2014]/g, '--').replace(/\u00A0/g, ' ');
  s = s.replace(/\u20B9/g, 'INR ').replace(/\u20AC/g, 'EUR ').replace(/\u00A3/g, 'GBP ').replace(/(?<!\\)\$/g, '\\$');
  s = s.replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '');
  return s;
}
const ctx = $('Load Revise Context').first().json;
const reviseType = ctx.last_apply.revise_type;
const revisedJson = $input.first().json.output || {};
const personal = ctx.last_apply.personal || {};
if (reviseType === 'cover') {
  const contentLines = [];
  contentLines.push('\\begin{lettercontent}');
  contentLines.push('\\begin{center}');
  contentLines.push('{\\large\\textbf{' + escapeLatexText(revisedJson.title || '') + '}}');
  contentLines.push('\\end{center}\n\\vspace{4mm}\n');
  contentLines.push(escapeLatexText(revisedJson.salutation || 'Dear Hiring Team,'));
  contentLines.push('');
  contentLines.push(escapeLatexText(revisedJson.hook || ''));
  contentLines.push('');
  contentLines.push('\\begin{itemize}[leftmargin=0.2in]');
  for (const bullet of (revisedJson.bullets || [])) {
    contentLines.push('  \\item \\textbf{' + escapeLatexText(cleanText(bullet.keyword || '')) + ':} ' + escapeLatexText(cleanText(bullet.text || '')));
  }
  contentLines.push('\\end{itemize}\n');
  contentLines.push(escapeLatexText(revisedJson.cta || ''));
  contentLines.push('\\end{lettercontent}');
  let fullLatex = wrapResumeWithSkeleton({ skeleton: ctx.cover_skeleton, headerLatex: '% Header omitted', contentLatex: contentLines.join('\n') });
  fullLatex = fullLatex.replace('{{NAME}}', escapeLatexText(personal.name || '')).replace('{{PHONE}}', escapeLatexText(personal.phone_display || personal.phone_primary || '')).replace('{{EMAIL}}', personal.email || '').replace('{{LINKEDIN}}', personal.linkedin || '');
  return [{ json: { latex: normalizeLatexForPdflatex(fullLatex), chat_id: ctx.chat_id, job_title: ctx.last_apply.job_title, company: ctx.last_apply.company, revise_type: 'cover', changes_summary: revisedJson.changes_summary || '' } }];
} else {
  const skeleton = ctx.last_apply.resume_skeleton;
  const headerTemplate = (() => { const lines = (skeleton || '').replace(/\r\n/g, '\n').split('\n'); const si = lines.findIndex(l => l.trim() === '%%% HEADER_START'); if (si === -1) return ''; const ei = lines.findIndex((l, i) => i > si && l.trim() === '%%% HEADER_END'); if (ei === -1) return ''; return lines.slice(si + 1, ei).join('\n').trim(); })();
  const headerLatex = headerTemplate.replace('{{NAME}}', escapeLatexText(personal.name || '')).replace('{{PHONE}}', escapeLatexText(personal.phone_display || personal.phone_primary || '')).replace('{{EMAIL}}', personal.email || '').replace('{{LINKEDIN}}', personal.linkedin || '').replace('{{PORTFOLIO_LINE}}', '').replace('{{GITHUB_LINE}}', '').replace('{{LOCATION_LINE}}', '');
  const sections = revisedJson.sections || [];
  const contentParts = [];
  for (const section of sections) {
    const heading = section.heading || '';
    const items = section.items || [];
    if (heading === 'Skills' || heading === 'Technical Skills') {
      contentParts.push('\\section{Technical Skills}\n\\resumeSubHeadingListStart');
      for (const item of items) { if (item.type === 'skill_line') contentParts.push('  \\resumeSkillLine{' + escapeLatexText(item.category || '') + '}{' + escapeLatexText(item.skills || '') + '}'); }
      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Education') {
      contentParts.push('\\section{Education}\n\\resumeSubHeadingListStart');
      for (const item of items) { if (item.type === 'education') { const degree = [item.degree, item.major].filter(Boolean).join(' in '); contentParts.push('  \\resumeSubheading{' + escapeLatexText(item.institution || '') + '}{' + escapeLatexText(item.location || '') + '}{' + escapeLatexText(degree) + '}{' + escapeLatexText(item.dates || '') + '}'); } }
      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Experience') {
      contentParts.push('\\section{Experience}\n\\resumeSubHeadingListStart');
      for (const item of items) {
        if (item.type === 'role') {
          contentParts.push('  \\resumeSubheading{' + escapeLatexText(item.role || '') + '}{' + escapeLatexText(item.dates || '') + '}{' + escapeLatexText(item.company || '') + '}{' + escapeLatexText(item.location || '') + '}');
          if (item.bullets && item.bullets.length > 0) { contentParts.push('  \\resumeItemListStart'); for (const b of item.bullets) { const kw = b.keyword ? '\\textbf{' + escapeLatexText(cleanText(b.keyword)) + ':} ' : ''; contentParts.push('    \\resumeItem{' + kw + escapeLatexText(cleanText(b.text || '')) + '}'); } contentParts.push('  \\resumeItemListEnd'); }
        }
      }
      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Projects') {
      contentParts.push('\\section{Projects}\n\\resumeSubHeadingListStart');
      for (const item of items) {
        if (item.type === 'project') {
          contentParts.push('  \\resumeProjectHeading{\\textbf{' + escapeLatexText(item.name || '') + '}' + (item.tech ? ' $|$ ' + escapeLatexText(item.tech) : '') + '}{' + (item.url ? escapeLatexText(item.url) : '') + '}');
          if (item.bullets && item.bullets.length > 0) { contentParts.push('  \\resumeItemListStart'); for (const b of item.bullets) { const kw = b.keyword ? '\\textbf{' + escapeLatexText(cleanText(b.keyword)) + ':} ' : ''; contentParts.push('    \\resumeItem{' + kw + escapeLatexText(cleanText(b.text || '')) + '}'); } contentParts.push('  \\resumeItemListEnd'); }
        }
      }
      contentParts.push('\\resumeSubHeadingListEnd');
    }
  }
  const fullLatex = wrapResumeWithSkeleton({ skeleton, headerLatex, contentLatex: contentParts.join('\n') });
  return [{ json: { latex: normalizeLatexForPdflatex(fullLatex), chat_id: ctx.chat_id, job_title: ctx.last_apply.job_title, company: ctx.last_apply.company, revise_type: 'resume', changes_summary: revisedJson.changes_summary || '' } }];
}

