// Normalize Firecrawl Search results → standard job object
// Native node shape: { success, data: { web: [...], news: [...], images: [...] } }

const hits = $input.all();
const allJobs = [];

function extractCompanyFromUrl(url) {
  let m;
  if ((m = url.match(/(?:boards|job-boards)\.greenhouse\.io\/(?:embed\/job_board\?for=)?([^/?&#]+)/))) return m[1];
  if ((m = url.match(/jobs\.lever\.co\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.ashbyhq\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/([^.\/]+)\.wd\d+\.myworkdayjobs\.com/))) return m[1];
  if ((m = url.match(/apply\.workable\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.smartrecruiters\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/workatastartup\.com\/jobs\/\d+\/[^?#]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/jobs\/[^/]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/company\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)\./))) return url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)/)[0];
  if ((m = url.match(/^https?:\/\/(?:www\.)?([^.]+)\./))) return m[1];
  return 'unknown';
}

function extractLocationFromTitle(title) {
  // Pull common location patterns out of titles like "ML Engineer - New York, NY"
  let m;
  if ((m = title.match(/(?:in|at|–|-|·|—)\s*([A-Z][\w\s]+,\s*[A-Z]{2,})/))) return m[1].trim();
  if ((m = title.match(/(?:in|at|–|-|·|—)\s*(New York|San Francisco|Seattle|Boston|Austin|Chicago|Los Angeles|Remote)/i))) return m[1];
  return '';
}

for (const item of hits) {
  if (item.json._disabled) continue;

  const data = item.json.data;
  let results = [];
  if (Array.isArray(data)) results = data;
  else if (data && Array.isArray(data.web)) results = data.web;
  else if (Array.isArray(item.json.results)) results = item.json.results;
  else if (Array.isArray(item.json.web)) results = item.json.web;

  for (const r of results) {
    const url = r.url || r.metadata?.sourceURL || '';
    if (!url) continue;
    const title = r.title || r.metadata?.title || '';
    const company = extractCompanyFromUrl(url);
    const location = r.metadata?.location || r.location || extractLocationFromTitle(title) || '';

    const __tier = classifyUrlTier(url);
    allJobs.push({
      job_id: 'fc-' + company + '-' + allJobs.length,
      title,
      company,
      location,
      department: '',
      url,
      description_snippet: (r.description || r.markdown || r.metadata?.description || '').substring(0, 600),
      updated_at: r.metadata?.publishedTime || r.publishedTime || '',
      source: 'firecrawl',
      source_tier: __tier.tier,
      tier_label: __tier.label
    });
  }
}

return [{ json: { jobs: allJobs, source: 'firecrawl', count: allJobs.length } }];

