  : "Searches will run silently\\. Send /verbose on anytime to re-enable\\.";
return [{ json: { message: `🔔 Verbose mode: *${state}*\n${detail}` } }];

// Schedule Gate
// Decides whether the current 3-hour tick fire matches a user-configured slot.
// Returns [] (silent short-circuit) if not.
//
// User prefs ($getWorkflowStaticData("global").user_prefs):
//   schedule_times: ["09:00", "18:00"]   (HH:MM 24h, 3-hour-aligned)
//                                         unset → use defaults
//                                         empty array → schedule disabled
//   timezone:       "America/New_York"   (IANA tz)
//
// Slots are rounded to the nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
// so any user-stored time matches the tick fires correctly.
// 30-minute last-fire guard prevents accidental double-fires.

const sd = $getWorkflowStaticData("global");
const prefs = sd.user_prefs || {};

let slots;
if (prefs.schedule_times === undefined) {
  slots = ["09:00", "18:00"];
} else if (Array.isArray(prefs.schedule_times) && prefs.schedule_times.length === 0) {
  return [];
} else if (Array.isArray(prefs.schedule_times)) {
  slots = prefs.schedule_times;
} else {
  slots = ["09:00", "18:00"];
}

const tz = prefs.timezone || "America/New_York";

const fmt = new Intl.DateTimeFormat("en-US", {
  timeZone: tz, hour12: false, hour: "2-digit", minute: "2-digit"
});
const parts = Object.fromEntries(fmt.formatToParts(new Date()).map(p => [p.type, p.value]));
const nowHHMM = `${parts.hour}:${parts.minute}`;

// Round HH:MM to nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
const round3h = (hhmm) => {
  const [h, m] = hhmm.split(":").map(Number);
  const totalMinutes = h * 60 + m;
  // 180 minutes = 3 hours
  const rounded = Math.round(totalMinutes / 180) * 180;
  const rh = String(Math.floor(rounded / 60) % 24).padStart(2, "0");
  return `${rh}:00`;
};

const nowSlot = round3h(nowHHMM);
const normalizedSlots = slots.map(round3h);
if (!normalizedSlots.includes(nowSlot)) return [];

// Last-fire guard: skip if same slot fired within last 30 minutes
sd._schedule_lastfire = sd._schedule_lastfire || {};
const lastFiredAt = sd._schedule_lastfire[nowSlot];
const nowMs = Date.now();
if (lastFiredAt && (nowMs - lastFiredAt) < 30 * 60 * 1000) return [];

sd._schedule_lastfire[nowSlot] = nowMs;
const cutoff = nowMs - 7 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(sd._schedule_lastfire)) {
  if (sd._schedule_lastfire[k] < cutoff) delete sd._schedule_lastfire[k];
}

return [{ json: { _slot: nowSlot, _tz: tz, _scheduled: true } }];

