const token = sd.telegraph_token || $env.TELEGRAPH_TOKEN || '';
const pageTitle = 'CareerForge — ' + rankedJobs.length + ' Jobs · ' + new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'});

return [{ json: {
