// Build Bubble Preview v2 — HTML-safe Telegram preview for resume_bubbles.
const upstream = $input.first().json || {};
const r = upstream.resume_doc;
const chatId = upstream.chat_id;

function arr(v) { return Array.isArray(v) ? v : []; }
function firstPrimary(a) { return arr(a).find(x => x && x.primary) || arr(a)[0] || {}; }
function clean(v) {
  const s = (v === null || v === undefined) ? '' : String(v).trim();
